// load time binding, addresses are relocated once, right before execution

relocatable_offset = 240;     // fixed by the compiler, unknown final location
load_base_address  = 7000;    // decided by the loader, right now, at load time

final_physical_address = load_base_address + relocatable_offset;
// final_physical_address is 7240, and it stays this value for the whole run

